    [2606] = {n="Un buen sabor", d="Marin Tragonublo quiere que hables con Roxio en Gadgetzan."},
    [2621] = {n="El deshonrado", d="Habla con el comandante de despachos Ruag en Rocal."},
    [2622] = {n="Las órdenes perdidas", d="Habla con Bengor."},
